int32_t exp_of(int32_t preset, int32_t adjustment) {
	const int32_t magnitude_increase = (adjustment >> 26) + 2;
	// The fine adjustment: less than one doubling.
	const int32_t adjusted = multiply_32x32_rshift32(
	    preset, interpolate_table_unsigned(adjustment & 67108863, 26, kExpTableSmall.data(), 8));
	return increase_magnitude_and_saturate(adjusted, magnitude_increase);
}

PanAmplitudes pan_amplitudes(int32_t pan) {
	if (pan == 0) {
		return {.left = 1073741823, .right = 1073741823};
	}
	const int32_t offset = std::max(static_cast<int32_t>(-1073741824), std::min(static_cast<int32_t>(1073741824), pan));
	return {.left = (pan <= 0) ? 1073741823 : (1073741824 - offset),
	        .right = (pan >= 0) ? 1073741823 : (1073741824 + offset)};
}

